<?php
require_once '/var/www/html/wp-load.php';$ids=get_posts(['post_type'=>'product','post_status'=>['publish','draft','pending','private'],'posts_per_page'=>-1,'fields'=>'ids']);$ready=0;$blocked=0;
foreach($ids as $id){$p=wc_get_product($id);if(!$p)continue;$state=(string)get_post_meta($id,'_bhc_catalog_quality_state',true);$source=(string)get_post_meta($id,'_bhc_source_url',true);$spec=json_decode((string)get_post_meta($id,'_bhc_structured_specs',true),true);$content=wp_strip_all_tags((string)$p->get_description());$img=(string)get_post_meta($id,'_bhc_image_generation_status',true);$ok=$state==='reference_verified'&&$source!==''&&is_array($spec)&&count($spec)>=3&&mb_strpos($content,'درباره محصول')!==false&&mb_strpos($content,'اطلاعات فنی')!==false&&mb_strpos($content,'پرسش‌های متداول')!==false&&$p->get_image_id()&&in_array($img,['generated_4k_transparent_verified','product_specific_generated','verified'],true);if($ok){update_post_meta($id,'_bhc_release_state','ready_for_release');update_post_meta($id,'_bhc_release_blocked','no');update_post_meta($id,'_bhc_release_gate_checked_at','2026-11-21');$ready++;}else{update_post_meta($id,'_bhc_release_state','blocked');update_post_meta($id,'_bhc_release_blocked','yes');$blocked++;}}
echo "RELEASE_GATE_READY|$ready\nRELEASE_GATE_BLOCKED|$blocked\n";
